-- private.bond_hash_seed(seed_text text)
CREATE OR REPLACE FUNCTION private.bond_hash_seed(seed_text text)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
declare
  h bigint := 2166136261;
  i integer;
begin
  if seed_text = '' then
    return h;
  end if;

  for i in 1..char_length(seed_text) loop
    h := ((h # ascii(substr(seed_text, i, 1))::bigint) * 16777619) % 4294967296;
  end loop;

  return h;
end;
$function$;

-- private.bond_mode_for_couple(target_couple_id uuid)
CREATE OR REPLACE FUNCTION private.bond_mode_for_couple(target_couple_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  lat1 double precision;
  lon1 double precision;
  lat2 double precision;
  lon2 double precision;
  hav double precision;
  km double precision;
begin
  select latitude, longitude
    into lat1, lon1
  from public.couple_locations
  where couple_id = target_couple_id
  order by user_id
  limit 1;

  select latitude, longitude
    into lat2, lon2
  from public.couple_locations
  where couple_id = target_couple_id
  order by user_id
  offset 1
  limit 1;

  if lat1 is null or lat2 is null then
    return 'any';
  end if;

  hav :=
    power(sin(radians((lat2 - lat1) / 2.0)), 2)
    + cos(radians(lat1)) * cos(radians(lat2))
      * power(sin(radians((lon2 - lon1) / 2.0)), 2);

  km := 6371.0 * 2.0 * asin(sqrt(least(1.0, greatest(0.0, hav))));
  return case when km > 50.0 then 'far' else 'near' end;
end;
$function$;

-- private.bond_week_start_rome(at_time timestamp with time zone)
CREATE OR REPLACE FUNCTION private.bond_week_start_rome(at_time timestamp with time zone DEFAULT now())
 RETURNS date
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
  select date_trunc('week', timezone('Europe/Rome', at_time))::date
$function$;

-- private.bucket_items_guard_calendar_link(p_couple_id uuid, p_calendar_entry_id uuid)
CREATE OR REPLACE FUNCTION private.bucket_items_guard_calendar_link(p_couple_id uuid, p_calendar_entry_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  -- Prefixed v_*: a bare `entry_type` here would be ambiguous with
  -- calendar_entries.entry_type in the SELECT below (PL/pgSQL cannot tell
  -- whether the target-list identifier means the variable or the column),
  -- so the source column is also alias-qualified (ce.*) to make the query
  -- side unambiguous too, not just the variable side.
  v_couple_id uuid;
  v_entry_type text;
begin
  if p_calendar_entry_id is null then
    return;
  end if;

  select ce.couple_id, ce.entry_type
  into v_couple_id, v_entry_type
  from public.calendar_entries ce
  where ce.id = p_calendar_entry_id;

  if v_couple_id is null then
    raise exception using errcode = '23503', message = 'bucket_items_calendar_entry_not_found';
  end if;

  if v_couple_id <> p_couple_id then
    raise exception using errcode = '42501', message = 'bucket_items_calendar_entry_cross_couple';
  end if;

  if v_entry_type <> 'shared' then
    raise exception using errcode = '42501', message = 'bucket_items_calendar_entry_not_shared';
  end if;
end;
$function$;

-- private.bucket_items_guard_delete()
CREATE OR REPLACE FUNCTION private.bucket_items_guard_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if old.status not in ('idea', 'archived') or old.calendar_entry_id is not null then
    raise exception using errcode = '42501', message = 'bucket_items_delete_requires_unlinked_idea_or_archived';
  end if;

  return old;
end;
$function$;

-- private.bucket_items_guard_insert()
CREATE OR REPLACE FUNCTION private.bucket_items_guard_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status is distinct from 'idea' then
    raise exception using errcode = '22023', message = 'bucket_items_insert_must_start_as_idea';
  end if;

  if new.completed then
    raise exception using errcode = '42501', message = 'bucket_items_lived_requires_reciprocal_confirmation';
  end if;

  if new.lived_proposed_by is not null or new.lived_proposed_at is not null then
    raise exception using errcode = '42501', message = 'bucket_items_lived_proposal_requires_confirm_rpc';
  end if;

  perform private.bucket_items_guard_calendar_link(new.couple_id, new.calendar_entry_id);

  new.completed := false;
  new.completed_at := null;
  return new;
end;
$function$;

-- private.bucket_items_guard_update()
CREATE OR REPLACE FUNCTION private.bucket_items_guard_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  repair_transfer boolean := coalesce(current_setting('us.bucket_items_repair_transfer', true), '') = 'on';
  lived_confirm boolean := coalesce(current_setting('us.bucket_items_lived_confirm', true), '') = 'on';
  resolved_status text := new.status;
begin
  if new.couple_id <> old.couple_id then
    raise exception using errcode = '42501', message = 'bucket_items_couple_id_immutable';
  end if;

  if new.created_by <> old.created_by and not repair_transfer then
    raise exception using errcode = '42501', message = 'bucket_items_created_by_immutable';
  end if;

  if new.status = old.status and new.completed and not old.completed then
    resolved_status := 'lived';
  end if;

  if new.status = old.status and old.status = 'lived' and not new.completed then
    raise exception using errcode = '22023', message = 'bucket_items_cannot_revert_lived_via_completed_flag';
  end if;

  if (new.lived_proposed_by is distinct from old.lived_proposed_by
      or new.lived_proposed_at is distinct from old.lived_proposed_at)
     and not lived_confirm then
    raise exception using errcode = '42501', message = 'bucket_items_lived_proposal_requires_confirm_rpc';
  end if;

  if resolved_status = 'lived' and old.status <> 'lived' and not lived_confirm then
    raise exception using errcode = '42501', message = 'bucket_items_lived_requires_reciprocal_confirmation';
  end if;

  if resolved_status <> old.status then
    if not (
      (old.status = 'idea' and resolved_status = 'scheduled')
      or (old.status = 'idea' and resolved_status = 'lived')
      or (old.status = 'scheduled' and resolved_status = 'lived')
      or (old.status = 'scheduled' and resolved_status = 'idea' and new.calendar_entry_id is null)
      or (old.status = 'idea' and resolved_status = 'archived')
      or (old.status = 'scheduled' and resolved_status = 'archived')
      or (old.status = 'lived' and resolved_status = 'archived')
    ) then
      raise exception using errcode = '22023', message = format('bucket_items_invalid_status_transition: %s -> %s', old.status, resolved_status);
    end if;
  end if;

  new.status := resolved_status;

  if new.calendar_entry_id is distinct from old.calendar_entry_id then
    perform private.bucket_items_guard_calendar_link(new.couple_id, new.calendar_entry_id);
  end if;

  if new.status = 'lived' then
    new.completed := true;
    new.completed_at := coalesce(old.completed_at, now());
  else
    new.completed := old.completed;
    new.completed_at := old.completed_at;
  end if;

  new.updated_at := now();
  return new;
end;
$function$;

-- private.bucket_items_release_archived_link()
CREATE OR REPLACE FUNCTION private.bucket_items_release_archived_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.status = 'archived' and new.completed_at is null and new.calendar_entry_id is not null then
    new.calendar_entry_id := null;
  end if;
  return new;
end;
$function$;

-- private.calendar_entries_guard_update()
CREATE OR REPLACE FUNCTION private.calendar_entries_guard_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  repair_transfer boolean := coalesce(current_setting('us.calendar_entries_repair_transfer', true), '') = 'on';
begin
  if new.entry_type <> old.entry_type then
    raise exception using errcode = '42501', message = 'calendar_entries_entry_type_immutable';
  end if;
  if new.couple_id <> old.couple_id then
    raise exception using errcode = '42501', message = 'calendar_entries_couple_id_immutable';
  end if;
  if new.created_by <> old.created_by and not repair_transfer then
    raise exception using errcode = '42501', message = 'calendar_entries_created_by_immutable';
  end if;
  new.updated_at := now();
  return new;
end;
$function$;

-- private.calendar_entries_unschedule_bucket_items()
CREATE OR REPLACE FUNCTION private.calendar_entries_unschedule_bucket_items()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update public.bucket_items
    set status = 'idea', calendar_entry_id = null
    where calendar_entry_id = old.id
      and couple_id = old.couple_id
      and status = 'scheduled';
  return old;
end;
$function$;

-- private.confirm_bond_quest_internal(target_quest_id uuid)
CREATE OR REPLACE FUNCTION private.confirm_bond_quest_internal(target_quest_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  q public.bond_weekly_quests%rowtype;
  uid uuid := auth.uid();
  cid uuid;
  next_confirmed uuid[];
  valid_confirmers integer;
  new_xp integer;
begin
  if uid is null then
    raise exception 'Not authenticated';
  end if;

  cid := private.current_couple_id();
  if cid is null then
    raise exception 'Couple not found';
  end if;

  select *
    into q
  from public.bond_weekly_quests
  where id = target_quest_id
    and couple_id = cid
  for update;

  if not found then
    raise exception 'Quest not found';
  end if;

  if q.week_start <> private.bond_week_start_rome(now()) then
    raise exception 'Quest week is closed';
  end if;

  if q.completed_at is not null then
    select bond_xp
      into new_xp
    from public.couples
    where id = q.couple_id;

    return jsonb_build_object(
      'completed', true,
      'bond_xp', new_xp,
      'confirmed_by', q.confirmed_by
    );
  end if;

  next_confirmed := coalesce(q.confirmed_by, '{}'::uuid[]);

  if array_position(next_confirmed, uid) is null then
    next_confirmed := array_append(next_confirmed, uid);
  end if;

  select count(distinct p.id)::integer
    into valid_confirmers
  from public.profiles p
  where p.couple_id = q.couple_id
    and p.id = any(next_confirmed);

  if valid_confirmers >= 2 then
    update public.bond_weekly_quests
      set confirmed_by = next_confirmed,
          completed_at = now()
    where id = q.id;

    update public.couples
      set bond_xp = bond_xp + q.xp
    where id = q.couple_id
    returning bond_xp into new_xp;

    insert into public.activity(couple_id, actor_id, type, payload)
    values (
      q.couple_id,
      uid,
      'bond_quest_completed',
      jsonb_build_object(
        'quest_id', q.id,
        'title', q.title,
        'xp', q.xp
      )
    );

    return jsonb_build_object(
      'completed', true,
      'bond_xp', new_xp,
      'confirmed_by', next_confirmed,
      'xp_awarded', q.xp
    );
  end if;

  update public.bond_weekly_quests
    set confirmed_by = next_confirmed
  where id = q.id;

  select bond_xp
    into new_xp
  from public.couples
  where id = q.couple_id;

  return jsonb_build_object(
    'completed', false,
    'bond_xp', new_xp,
    'confirmed_by', next_confirmed
  );
end;
$function$;

