-- private.daily_question_keepsakes_guard_update()
CREATE OR REPLACE FUNCTION private.daily_question_keepsakes_guard_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  raise exception using errcode = '42501', message = 'daily_question_keepsake_immutable';
end;
$function$;

-- private.daily_question_reveal_ready(target_question_id uuid)
CREATE OR REPLACE FUNCTION private.daily_question_reveal_ready(target_question_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(
    (public.get_daily_state(target_question_id)->>'both_answered')::boolean,
    false
  );
$function$;
comment on function private.daily_question_reveal_ready(target_question_id uuid) is 'M3 helper only: delegates reveal semantics to public.get_daily_state and extracts both_answered.';

-- private.daily_reveal_context(target_question_id uuid)
CREATE OR REPLACE FUNCTION private.daily_reveal_context(target_question_id uuid)
 RETURNS TABLE(caller_couple uuid, caller_role text, ready boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_couple uuid;
  actor_role text;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'authentication required';
  end if;
  if target_question_id is null then
    raise exception using errcode = '22004', message = 'question id required';
  end if;

  select profile.couple_id, profile.role
    into current_couple, actor_role
    from public.profiles as profile
   where profile.id = auth.uid()
     and profile.couple_id is not null;

  if current_couple is null or actor_role not in ('francesco', 'beatrice') then
    raise exception using errcode = '42501', message = 'couple membership required';
  end if;

  return query select current_couple, actor_role, private.daily_question_reveal_ready(target_question_id);
end;
$function$;

-- private.daily_reveal_meta(target_question_id uuid, current_couple uuid, caller_role text, ready boolean)
CREATE OR REPLACE FUNCTION private.daily_reveal_meta(target_question_id uuid, current_couple uuid, caller_role text, ready boolean)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'question_id', target_question_id,
    'both_answered', ready,
    'my_reveal_seen_at', case when ready then mine.reveal_seen_at end,
    'my_notice_dismissed_at', case when ready then mine.notice_dismissed_at end,
    'my_reaction', case when ready then mine.reaction end,
    'partner_reaction', case when ready then partner.reaction end
  )
  from (select 1) as anchor
  left join public.daily_question_reveal_states as mine
    on mine.couple_id = current_couple and mine.question_id = target_question_id and mine.actor_role = daily_reveal_meta.caller_role
  left join public.daily_question_reveal_states as partner
    on partner.couple_id = current_couple and partner.question_id = target_question_id and partner.actor_role <> daily_reveal_meta.caller_role;
$function$;

-- private.ensure_bond_week_internal()
CREATE OR REPLACE FUNCTION private.ensure_bond_week_internal()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  uid uuid := auth.uid();
  cid uuid;
  week date;
  quest_mode text;
  slot_no integer;
  pool text[];
  candidates text[];
  used_keys text[];
  picked_key text;
  picked public.bond_quest_templates%rowtype;
  pick_index integer;
  quest_count integer;
begin
  if uid is null then
    raise exception 'Not authenticated';
  end if;

  cid := private.current_couple_id();
  if cid is null then
    raise exception 'Couple not found';
  end if;

  week := private.bond_week_start_rome(now());

  insert into public.bond_weekly_state(couple_id, week_start, rerolls_used)
  values (cid, week, 0)
  on conflict (couple_id, week_start) do nothing;

  perform 1
  from public.bond_weekly_state
  where couple_id = cid and week_start = week
  for update;

  quest_mode := private.bond_mode_for_couple(cid);

  for slot_no in 1..3 loop
    if exists (
      select 1
      from public.bond_weekly_quests
      where couple_id = cid
        and week_start = week
        and slot = slot_no
    ) then
      continue;
    end if;

    select coalesce(array_agg(template_key order by template_key), '{}'::text[])
      into used_keys
    from public.bond_weekly_quests
    where couple_id = cid
      and week_start = week;

    select array_agg(t.key order by t.key)
      into pool
    from public.bond_quest_templates t
    where t.active = true
      and (t.mode = 'any' or t.mode = quest_mode)
      and (
        (slot_no = 1 and t.rarity in ('common', 'uncommon'))
        or (slot_no = 2 and t.rarity in ('uncommon', 'rare'))
        or (slot_no = 3 and t.rarity in ('rare', 'epic'))
      );

    if coalesce(cardinality(pool), 0) = 0 then
      select array_agg(t.key order by t.key)
        into pool
      from public.bond_quest_templates t
      where t.active = true
        and (t.mode = 'any' or t.mode = quest_mode);
    end if;

    select array_agg(k order by k)
      into candidates
    from unnest(coalesce(pool, '{}'::text[])) as k
    where not (k = any(coalesce(used_keys, '{}'::text[])));

    if coalesce(cardinality(candidates), 0) = 0 then
      continue;
    end if;

    pick_index :=
      (private.bond_hash_seed(
        cid::text || '|' || week::text || '|' || slot_no::text || '|bond'
      ) % cardinality(candidates))::integer + 1;

    picked_key := candidates[pick_index];

    select *
      into picked
    from public.bond_quest_templates
    where key = picked_key
      and active = true;

    if not found then
      raise exception 'Quest template disappeared during initialization';
    end if;

    insert into public.bond_weekly_quests(
      couple_id,
      week_start,
      slot,
      template_key,
      title,
      category,
      rarity,
      xp,
      confirmed_by,
      completed_at
    )
    values (
      cid,
      week,
      slot_no,
      picked.key,
      picked.title,
      picked.category,
      picked.rarity,
      picked.xp,
      '{}'::uuid[],
      null
    )
    on conflict (couple_id, week_start, slot) do nothing;
  end loop;

  select count(*)::integer
    into quest_count
  from public.bond_weekly_quests
  where couple_id = cid
    and week_start = week;

  return jsonb_build_object(
    'week_start', week,
    'mode', quest_mode,
    'quest_count', quest_count
  );
end;
$function$;

-- private.game_v2_assign_subjects(target_couple uuid, items jsonb, heavy text)
CREATE OR REPLACE FUNCTION private.game_v2_assign_subjects(target_couple uuid, items jsonb, heavy text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare n integer; heavy_left integer; other_left integer; other text := private.game_v2_partner_role(heavy);
  subjects text[]; e jsonb; k integer := 0; pref text; alt integer := 0;
begin
  select count(*) into n from jsonb_array_elements(items) x where x->>'mechanic' = 'prediction';
  heavy_left := (n + 1) / 2; other_left := n / 2;
  subjects := array_fill(null::text, array[greatest(jsonb_array_length(items), 1)]);
  -- Pass 1: rotate the perspective of prompts the couple already played.
  for e in select value from jsonb_array_elements(items) loop
    k := k + 1;
    continue when e->>'mechanic' <> 'prediction';
    select private.game_v2_partner_role(i.subject_role) into pref
      from public.game_session_items i join public.game_sessions s on s.id = i.session_id
      where s.couple_id = target_couple and s.engine_version = 2 and i.fingerprint = e->>'candidate_key'
        and i.subject_role is not null
      order by s.started_at desc limit 1;
    if pref = heavy and heavy_left > 0 then subjects[k] := heavy; heavy_left := heavy_left - 1;
    elsif pref = other and other_left > 0 then subjects[k] := other; other_left := other_left - 1;
    end if;
  end loop;
  -- Pass 2: the rest alternate, heavy first, within the remaining split.
  k := 0;
  for e in select value from jsonb_array_elements(items) loop
    k := k + 1;
    continue when e->>'mechanic' <> 'prediction' or subjects[k] is not null;
    if (alt % 2 = 0 and heavy_left > 0) or other_left = 0 then subjects[k] := heavy; heavy_left := heavy_left - 1;
    else subjects[k] := other; other_left := other_left - 1; end if;
    alt := alt + 1;
  end loop;
  return (select coalesce(jsonb_agg(case when x.value->>'mechanic' = 'prediction'
      then x.value || jsonb_build_object('subject_role', subjects[x.ordinality::integer]) else x.value end
      order by x.ordinality), '[]'::jsonb)
    from jsonb_array_elements(items) with ordinality x);
end;
$function$;

-- private.game_v2_candidates(target_couple uuid, target_family text, at_time timestamp with time zone)
CREATE OR REPLACE FUNCTION private.game_v2_candidates(target_couple uuid, target_family text, at_time timestamp with time zone)
 RETURNS SETOF private.game_v2_candidate
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select ('catalog:' || c.id), c.family, c.mechanic, c.answer_kind, c.question_text, c.predict_text,
    c.options, c.depth, c.topic, 'curated', c.id, c.id, c.version, null::uuid, null::integer,
    '{}'::jsonb, c.cooldown_class, 50 + 3 * (c.depth - 1), null::integer, null::boolean, null::timestamptz
  from public.game_v2_catalog c
  where c.active and c.source_type = 'curated' and (target_family = 'per_voi' or c.family = target_family)
  union all
  -- Couple-authored questions (weekly and M11A library). Unplayed ones are
  -- the most authentic content available and rank first.
  select ('custom:' || q.id::text), fam.family,
    case when fam.family = 'quanto_mi_conosci' then 'prediction' else 'reciprocal' end,
    q.answer_kind, q.question_text,
    case when fam.family = 'quanto_mi_conosci' then q.question_text end,
    q.options, 2::smallint, ('custom_' || replace(q.id::text, '-', '_')), 'couple_custom', q.id::text,
    null::text, null::integer, q.id, q.version,
    jsonb_build_object('author_role', q.author_role, 'origin', q.origin),
    'custom',
    case when played.at is not null then 35 when q.origin = 'weekly' then 95 else 85 end,
    null::integer, null::boolean, null::timestamptz
  from public.couple_questions q
  cross join lateral (select case when target_family = 'per_voi' then q.families[1] else target_family end as family) fam
  left join lateral (select max(s.started_at) as at from public.game_session_items i
    join public.game_sessions s on s.id = i.session_id where i.source_question_id = q.id) played on true
  where q.couple_id = target_couple and q.archived_at is null
    and (target_family = 'per_voi' or target_family = any (q.families))
    and (fam.family <> 'quanto_mi_conosci' or q.answer_kind = 'choice')
  union all
  select * from private.game_v2_context_candidates(target_couple, target_family, at_time);
$function$;

-- private.game_v2_clean_title(raw text)
CREATE OR REPLACE FUNCTION private.game_v2_clean_title(raw text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case when t is null or char_length(t) not between 3 and 60 or t !~ '[[:alpha:]]'
      or t ~* '(https?://|www\.|[a-z0-9-]+\.(com|it|net|org)\y)' then null else t end
  from (select nullif(btrim(regexp_replace(translate(coalesce(raw, ''), '«»“”"', '     '), '\s+', ' ', 'g')), '') t) x;
$function$;

-- private.game_v2_clock()
CREATE OR REPLACE FUNCTION private.game_v2_clock()
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$ select now() $function$;

-- private.game_v2_context_candidates(target_couple uuid, target_family text, at_time timestamp with time zone)
CREATE OR REPLACE FUNCTION private.game_v2_context_candidates(target_couple uuid, target_family text, at_time timestamp with time zone)
 RETURNS SETOF private.game_v2_candidate
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select * from private.game_v2_ctx_da_vivere(target_couple, target_family, at_time)
  union all select * from private.game_v2_ctx_calendar(target_couple, target_family, at_time)
  union all select * from private.game_v2_ctx_moments(target_couple, target_family, at_time)
  union all select * from private.game_v2_ctx_conservati(target_couple, target_family, at_time)
  union all select * from private.game_v2_ctx_longitudinal(target_couple, target_family, at_time);
$function$;

-- private.game_v2_ctx_calendar(target_couple uuid, target_family text, at_time timestamp with time zone)
CREATE OR REPLACE FUNCTION private.game_v2_ctx_calendar(target_couple uuid, target_family text, at_time timestamp with time zone)
 RETURNS SETOF private.game_v2_candidate
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare upcoming jsonb; past jsonb; at_date date := (at_time at time zone 'Europe/Rome')::date;
  week text := private.game_v2_week_start(at_time)::text;
begin
  -- Shared entries only; an entry already represented by a Da vivere item is
  -- left to that adapter so the same plan never appears twice.
  with shared as (
    select e.id, private.game_v2_clean_title(e.title) title,
      coalesce((e.starts_at at time zone 'Europe/Rome')::date, e.start_date) as on_day
    from public.calendar_entries e
    where e.couple_id = target_couple and e.entry_type = 'shared'
      and not exists (select 1 from public.bucket_items b where b.calendar_entry_id = e.id)
  )
  select
    coalesce((select jsonb_agg(x.src) from (
      select jsonb_build_object('id', s.id::text, 'title', s.title, 'date', private.game_v2_day_label(s.on_day)) src
      from shared s where s.title is not null and s.on_day between at_date + 1 and at_date + 60
      order by s.on_day, s.id limit 4) x), '[]'::jsonb),
    coalesce((select jsonb_agg(x.src) from (
      select jsonb_build_object('id', s.id::text, 'title', s.title, 'when', private.game_v2_when_label(s.on_day, at_date)) src
      from shared s where s.title is not null and s.on_day between at_date - 365 and at_date - 7
      order by md5(target_couple::text || ':' || s.id::text || ':' || week) limit 4) x), '[]'::jsonb)
  into upcoming, past;
  return query select * from private.game_v2_recipe_candidates(target_family, 'calendar_upcoming', 'calendar', upcoming, at_time);
  return query select * from private.game_v2_recipe_candidates(target_family, 'calendar_past', 'calendar', past, at_time);
exception when others then
  raise warning 'game_v2 context adapter calendar skipped: %', sqlerrm;
  return;
end;
$function$;

-- private.game_v2_ctx_conservati(target_couple uuid, target_family text, at_time timestamp with time zone)
CREATE OR REPLACE FUNCTION private.game_v2_ctx_conservati(target_couple uuid, target_family text, at_time timestamp with time zone)
 RETURNS SETOF private.game_v2_candidate
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare kept boolean;
begin
  select exists (select 1 from public.conserva_contributions c
    where c.couple_id = target_couple and c.created_at between at_time - interval '365 days' and at_time) into kept;
  if not kept then return; end if;
  return query select * from private.game_v2_recipe_candidates(target_family, 'conservati', 'conservati',
    jsonb_build_array(jsonb_build_object('id', 'conservati')), at_time);
exception when others then
  raise warning 'game_v2 context adapter conservati skipped: %', sqlerrm;
  return;
end;
$function$;

-- private.game_v2_ctx_da_vivere(target_couple uuid, target_family text, at_time timestamp with time zone)
CREATE OR REPLACE FUNCTION private.game_v2_ctx_da_vivere(target_couple uuid, target_family text, at_time timestamp with time zone)
 RETURNS SETOF private.game_v2_candidate
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare ideas jsonb; lived jsonb; at_date date := (at_time at time zone 'Europe/Rome')::date;
  week text := private.game_v2_week_start(at_time)::text;
begin
  select coalesce(jsonb_agg(x.src), '[]'::jsonb) into ideas from (
    select jsonb_build_object('id', b.id::text, 'title', t.title) src
    from public.bucket_items b cross join lateral (select private.game_v2_clean_title(b.title) title) t
    where b.couple_id = target_couple and b.status in ('idea', 'scheduled') and t.title is not null
    order by md5(target_couple::text || ':' || b.id::text || ':' || week) limit 4) x;
  select coalesce(jsonb_agg(x.src), '[]'::jsonb) into lived from (
    select jsonb_build_object('id', b.id::text, 'title', t.title,
      'when', private.game_v2_when_label((b.completed_at at time zone 'Europe/Rome')::date, at_date)) src
    from public.bucket_items b cross join lateral (select private.game_v2_clean_title(b.title) title) t
    where b.couple_id = target_couple and b.status = 'lived' and t.title is not null
      and b.completed_at is not null
      and (b.completed_at at time zone 'Europe/Rome')::date between at_date - 730 and at_date - 3
    order by md5(target_couple::text || ':' || b.id::text || ':' || week) limit 4) x;
  return query select * from private.game_v2_recipe_candidates(target_family, 'da_vivere_idea', 'da_vivere', ideas, at_time);
  return query select * from private.game_v2_recipe_candidates(target_family, 'da_vivere_lived', 'da_vivere', lived, at_time);
exception when others then
  raise warning 'game_v2 context adapter da_vivere skipped: %', sqlerrm;
  return;
end;
$function$;

-- private.game_v2_ctx_longitudinal(target_couple uuid, target_family text, at_time timestamp with time zone)
CREATE OR REPLACE FUNCTION private.game_v2_ctx_longitudinal(target_couple uuid, target_family text, at_time timestamp with time zone)
 RETURNS SETOF private.game_v2_candidate
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare at_date date := (at_time at time zone 'Europe/Rome')::date;
begin
  return query
  with plays as (
    select i.id item_id, i.source_ref catalog_id, s.started_at, s.completed_at,
      (select count(*) from public.game_session_answers a where a.item_id = i.id and a.answer_text is not null) answered
    from public.game_session_items i join public.game_sessions s on s.id = i.session_id
    where s.couple_id = target_couple and s.engine_version = 2 and i.source_type in ('curated', 'game_history')
  ), last_play as (
    select distinct on (p.catalog_id) p.catalog_id, p.started_at last_started from plays p
    order by p.catalog_id, p.started_at desc
  ), previous as (
    select distinct on (p.catalog_id) p.catalog_id, p.item_id, p.started_at, p.completed_at from plays p
    where p.completed_at is not null and p.answered = 2
    order by p.catalog_id, p.completed_at desc
  )
  select ('longitudinal:' || c.id), c.family, 'reciprocal'::text, 'open'::text,
    private.game_v2_fill(r.question_text, jsonb_build_object('previous_question', c.question_text)),
    null::text, '[]'::jsonb, c.depth, c.topic, 'game_history'::text, c.id, r.id, r.version, null::uuid, null::integer,
    jsonb_build_object('kind', 'longitudinal',
      'kind_label', private.game_v2_fill(r.kind_label, jsonb_build_object('when',
        private.game_v2_when_label((pv.started_at at time zone 'Europe/Rome')::date, at_date))),
      'source_type', 'game_history', 'source_id', c.id, 'previous_item_id', pv.item_id,
      'previous_played_at', pv.started_at, 'recipe_id', r.id, 'recipe_version', r.version, 'captured_at', at_time),
    r.cooldown_class, 72, null::integer, null::boolean, null::timestamptz
  from public.game_v2_catalog c
  join previous pv on pv.catalog_id = c.id
  join last_play lp on lp.catalog_id = c.id
  join public.game_v2_recipes r on r.adapter = 'longitudinal' and r.active
  where c.active and c.longitudinal and c.mechanic = 'reciprocal' and c.answer_kind = 'open'
    and (target_family = 'per_voi' or c.family = target_family)
    and lp.last_started <= at_time - interval '90 days'
  -- One resurfacing at a time: the prompt answered longest ago.
  order by pv.started_at, c.id
  limit 1;
exception when others then
  raise warning 'game_v2 context adapter longitudinal skipped: %', sqlerrm;
  return;
end;
$function$;

-- private.game_v2_ctx_moments(target_couple uuid, target_family text, at_time timestamp with time zone)
CREATE OR REPLACE FUNCTION private.game_v2_ctx_moments(target_couple uuid, target_family text, at_time timestamp with time zone)
 RETURNS SETOF private.game_v2_candidate
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare src jsonb; at_date date := (at_time at time zone 'Europe/Rome')::date;
  week text := private.game_v2_week_start(at_time)::text;
begin
  select coalesce(jsonb_agg(x.src), '[]'::jsonb) into src from (
    select jsonb_build_object('id', coalesce(p.source_ref, m.id)::text, 'title', t.title,
      'when', private.game_v2_when_label(t.on_day, at_date), 'origin', coalesce(p.source_kind, 'moment')) src
    from public.moments m
    left join public.living_provenance p
      on p.target_kind = 'moment' and p.target_ref = m.id and p.couple_id = m.couple_id
    cross join lateral (select private.game_v2_clean_title(m.caption) title,
      coalesce(m.moment_date, (m.created_at at time zone 'Europe/Rome')::date) as on_day) t
    where m.couple_id = target_couple and t.title is not null and t.on_day between at_date - 730 and at_date - 14
    order by md5(target_couple::text || ':' || m.id::text || ':' || week) limit 4) x;
  return query select * from private.game_v2_recipe_candidates(target_family, 'moment', 'moment',
    (select coalesce(jsonb_agg(s), '[]'::jsonb) from jsonb_array_elements(src) s where s->>'origin' = 'moment'), at_time);
  return query select * from private.game_v2_recipe_candidates(target_family, 'moment', 'da_vivere',
    (select coalesce(jsonb_agg(s), '[]'::jsonb) from jsonb_array_elements(src) s where s->>'origin' = 'da_vivere'), at_time);
  return query select * from private.game_v2_recipe_candidates(target_family, 'moment', 'shared_event_completion',
    (select coalesce(jsonb_agg(s), '[]'::jsonb) from jsonb_array_elements(src) s where s->>'origin' = 'shared_event_completion'), at_time);
exception when others then
  raise warning 'game_v2 context adapter moments skipped: %', sqlerrm;
  return;
end;
$function$;

-- private.game_v2_day_label(d date)
CREATE OR REPLACE FUNCTION private.game_v2_day_label(d date)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select extract(day from d)::integer::text || ' ' || private.game_v2_month_name(d);
$function$;

-- private.game_v2_families()
CREATE OR REPLACE FUNCTION private.game_v2_families()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select array['scopritevi', 'confrontatevi', 'ridete', 'quanto_mi_conosci', 'rivivete', 'e_se']::text[];
$function$;

-- private.game_v2_fill(template text, source jsonb)
CREATE OR REPLACE FUNCTION private.game_v2_fill(template text, source jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select replace(replace(replace(replace(template,
    '{title}', coalesce(source->>'title', '')), '{date}', coalesce(source->>'date', '')),
    '{when}', coalesce(source->>'when', '')), '{previous_question}', coalesce(source->>'previous_question', ''));
$function$;

