  return new;
end;
$function$;

-- public.ack_progression_unlock(target_reward_id text)
CREATE OR REPLACE FUNCTION public.ack_progression_unlock(target_reward_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  uid uuid := auth.uid();
  cid uuid;
begin
  if uid is null then raise exception using errcode = '42501', message = 'authentication required'; end if;
  select p.couple_id into cid from public.profiles p where p.id = uid;
  if cid is null then raise exception using errcode = '42501', message = 'couple membership required'; end if;
  if not exists (
    select 1 from public.couple_reward_unlocks u
     where u.couple_id = cid and u.reward_id = target_reward_id
  ) then
    raise exception using errcode = '42501', message = 'reward not unlocked';
  end if;
  insert into public.progression_reward_views(couple_id, reward_id, profile_id)
  values (cid, target_reward_id, uid)
  on conflict (couple_id, reward_id, profile_id) do nothing;
  return jsonb_build_object('acknowledged', true, 'reward_id', target_reward_id);
end;
$function$;

-- public.archive_couple_question(target_question_id uuid)
CREATE OR REPLACE FUNCTION public.archive_couple_question(target_question_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor record; q public.couple_questions%rowtype;
begin
  select * into actor from private.m11a_actor_locked();
  select * into q from public.couple_questions
    where id = target_question_id and couple_id = actor.caller_couple for update;
  if q.id is null then raise exception using errcode = '42501', message = 'question unavailable'; end if;
  if q.author_role <> actor.caller_role then raise exception using errcode = '42501', message = 'author only'; end if;
  update public.couple_questions set archived_at = coalesce(archived_at, now()), updated_at = now()
    where id = q.id and archived_at is null;
  return jsonb_build_object('id', q.id, 'archived', true);
end;
$function$;
comment on function public.archive_couple_question(target_question_id uuid) is 'RETIRED (US 2.0 F1B): M11A, superseded by Game V2. EXECUTE revoked from public/anon/authenticated.';

-- public.award_relationship_milestone(target_couple_id uuid, target_milestone_date date, target_months integer, target_kind text, target_xp integer)
CREATE OR REPLACE FUNCTION public.award_relationship_milestone(target_couple_id uuid, target_milestone_date date, target_months integer, target_kind text, target_xp integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare inserted_id uuid;
begin
  if target_months<=0 or target_xp<0 or target_xp>500 or target_kind not in ('monthiversary','anniversary') then raise exception 'Invalid milestone'; end if;
  insert into public.relationship_milestones(couple_id,milestone_date,kind,months_together,xp_awarded)
  values(target_couple_id,target_milestone_date,target_kind,target_months,target_xp)
  on conflict(couple_id,milestone_date,kind) do nothing
  returning id into inserted_id;
  if inserted_id is null then return false; end if;
  update public.couples set bond_xp=coalesce(bond_xp,0)+target_xp where id=target_couple_id;
  insert into public.activity(couple_id,actor_id,type,payload)
  values(target_couple_id,null,'relationship_milestone',jsonb_build_object('date',target_milestone_date,'months',target_months,'kind',target_kind,'xp',target_xp));
  return true;
end; $function$;

