$function$;

-- public.claim_left_for_you_cleanup(target_batch_size integer)
CREATE OR REPLACE FUNCTION public.claim_left_for_you_cleanup(target_batch_size integer DEFAULT 100)
 RETURNS TABLE(item_id uuid, couple_id uuid, sender_id uuid, kind text, media_path text, source_deleted_at timestamp with time zone, claimed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  requested_batch integer := greatest(1, least(coalesce(target_batch_size, 100), 500));
begin
  update private.left_for_you_cleanup_queue as stale
  set claimed_at = null
  where stale.completed_at is null
    and stale.claimed_at < now() - interval '15 minutes';

  insert into private.left_for_you_cleanup_queue
    (item_id, couple_id, sender_id, kind, media_path)
  select
    item.id,
    item.couple_id,
    item.sender_id,
    item.kind,
    item.media_path
  from public.left_for_you as item
  where item.cleanup_eligible_at is not null
    and item.seen_at is not null
    and item.seen_at < now() - interval '30 days'
    and not exists (
      select 1
      from public.conserva_contributions as contribution
      where contribution.source_item_id = item.id
    )
    and not exists (
      select 1
      from private.left_for_you_cleanup_queue as queued
      where queued.item_id = item.id
        and queued.completed_at is null
    )
  on conflict on constraint left_for_you_cleanup_queue_pkey do nothing;

  return query
  with claimable as (
    select queue.item_id
    from private.left_for_you_cleanup_queue as queue
    where queue.completed_at is null
      and queue.claimed_at is null
    order by queue.source_deleted_at nulls first, queue.item_id
    limit requested_batch
    for update skip locked
  )
  update private.left_for_you_cleanup_queue as queue
  set claimed_at = now()
  from claimable
  where queue.item_id = claimable.item_id
  returning queue.item_id, queue.couple_id, queue.sender_id, queue.kind,
    queue.media_path, queue.source_deleted_at, queue.claimed_at;
end;
$function$;

-- public.claim_us_role(invite_code text, chosen_role text)
CREATE OR REPLACE FUNCTION public.claim_us_role(invite_code text, chosen_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
declare
  uid uuid := auth.uid();
  inv public.couple_invites%rowtype;
  old_uid uuid;
  old_avatar text;
  old_created_at timestamptz;
  display text;
  is_anon boolean;
begin
  if uid is null then
    raise exception 'Authentication required';
  end if;

  select coalesce((raw_app_meta_data->>'provider') = 'anonymous', false)
      or coalesce((raw_user_meta_data->>'is_anonymous')::boolean, false)
      or email is null
  into is_anon
  from auth.users where id = uid;

  if not coalesce(is_anon, false) then
    raise exception 'Anonymous session required for private pairing';
  end if;

  if chosen_role not in ('francesco','beatrice') then
    raise exception 'Invalid role';
  end if;

  select * into inv
  from public.couple_invites
  where code_hash = encode(extensions.digest(upper(trim(invite_code))::text, 'sha256'::text), 'hex')
    and role = chosen_role
  for update;

  if inv.id is null then
    raise exception 'Invalid private code';
  end if;

  if exists (
    select 1 from public.profiles
    where id = uid and (couple_id is distinct from inv.couple_id or role is distinct from chosen_role)
  ) then
    raise exception 'This device is already linked to another profile';
  end if;

  select id, avatar_path, created_at
  into old_uid, old_avatar, old_created_at
  from public.profiles
  where couple_id = inv.couple_id and role = chosen_role
  limit 1
  for update;

  display := case chosen_role when 'francesco' then 'Francesco' else 'Beatrice' end;

  if old_uid is not null and old_uid <> uid then
    -- Temporarily remove the old profile from the partial unique index
    -- (couple_id, role) while keeping the profile row alive for FK safety.
    update public.profiles
    set couple_id = null
    where id = old_uid;

    -- Create the replacement profile BEFORE moving profile-owned foreign keys.
    insert into public.profiles(id, display_name, couple_id, role, created_at, avatar_path)
    values (uid, display, inv.couple_id, chosen_role, coalesce(old_created_at, now()), old_avatar)
    on conflict (id) do update
      set display_name = excluded.display_name,
          couple_id = excluded.couple_id,
          role = excluded.role,
          avatar_path = coalesce(excluded.avatar_path, public.profiles.avatar_path);

    -- Core historical data.
    update public.daily_answers set user_id = uid where user_id = old_uid and couple_id = inv.couple_id;
    update public.quiz_responses set user_id = uid where user_id = old_uid and couple_id = inv.couple_id;
    -- M7A: bucket_items now carries a created_by-immutability guard trigger
    -- (20260929090000). The trigger blocks this reassignment by default;
    -- this session-local flag authorises exactly this one statement, for
    -- exactly this transfer, mirroring the calendar_entries carve-out below.
    perform set_config('us.bucket_items_repair_transfer', 'on', true);
    update public.bucket_items set created_by = uid where created_by = old_uid and couple_id = inv.couple_id;
    perform set_config('us.bucket_items_repair_transfer', 'off', true);
    update public.shared_messages set sender_id = uid where sender_id = old_uid and couple_id = inv.couple_id;
    update public.shared_messages set recipient_id = uid where recipient_id = old_uid and couple_id = inv.couple_id;
    update public.moods set user_id = uid where user_id = old_uid and couple_id = inv.couple_id;
    update public.activity set actor_id = uid where actor_id = old_uid and couple_id = inv.couple_id;

    -- Current US 1.0 profile-owned data.
    update public.couple_locations set user_id = uid where user_id = old_uid and couple_id = inv.couple_id;
    update public.device_push_tokens set user_id = uid where user_id = old_uid and couple_id = inv.couple_id;
    update public.moments set created_by = uid where created_by = old_uid and couple_id = inv.couple_id;
    update public.moment_photos set created_by = uid where created_by = old_uid and couple_id = inv.couple_id;
    update public.notification_preferences set user_id = uid where user_id = old_uid;
    update public.partner_knowledge_attempts set user_id = uid where user_id = old_uid and couple_id = inv.couple_id;
    update public.push_event_log set sender_id = uid where sender_id = old_uid and couple_id = inv.couple_id;
    update public.push_subscriptions set user_id = uid where user_id = old_uid and couple_id = inv.couple_id;
    update public.shared_event_completions set completed_by = uid where completed_by = old_uid and couple_id = inv.couple_id;
    update public.shared_events set created_by = uid where created_by = old_uid and couple_id = inv.couple_id;
    update public.stories set author_id = uid where author_id = old_uid and couple_id = inv.couple_id;
    update public.story_views set viewer_id = uid where viewer_id = old_uid;
    update public.widget_tokens set profile_id = uid where profile_id = old_uid and couple_id = inv.couple_id;

    -- M6A: calendar_entries (added by 20260928071749, not part of the
    -- original production function). owner_id and created_by move together
    -- in one statement so a personal row never has owner_id <> created_by
    -- mid-transfer (calendar_entries_personal_owner_is_creator_check would
    -- otherwise reject it); shared rows keep owner_id null and only
    -- created_by moves. The guard trigger blocks created_by changes by
    -- default, so this session-local flag authorises exactly this transfer,
    -- for exactly this one statement.
    perform set_config('us.calendar_entries_repair_transfer', 'on', true);
    update public.calendar_entries
    set created_by = uid,
        owner_id = case when owner_id = old_uid then uid else owner_id end
    where couple_id = inv.couple_id
      and (created_by = old_uid or owner_id = old_uid);
    perform set_config('us.calendar_entries_repair_transfer', 'off', true);

    update public.couple_invites set used_by = uid, used_at = now() where id = inv.id;

    -- All references now point to the new profile, so this delete is safe.
    delete from public.profiles where id = old_uid;
  else
    insert into public.profiles(id, display_name, couple_id, role, avatar_path)
    values (uid, display, inv.couple_id, chosen_role, old_avatar)
    on conflict (id) do update
      set display_name = excluded.display_name,
          couple_id = excluded.couple_id,
          role = excluded.role,
          avatar_path = coalesce(excluded.avatar_path, public.profiles.avatar_path);
  end if;

  update public.couple_invites
  set used_by = uid, used_at = now()
  where id = inv.id;

  return jsonb_build_object('couple_id', inv.couple_id, 'role', chosen_role, 'display_name', display);
end;
$function$;
comment on function public.claim_us_role(invite_code text, chosen_role text) is 'RETIRED (US 2.0 F1A): legacy anonymous pairing. EXECUTE revoked from public/anon/authenticated; login is email + password only. Kept for migration-history compatibility; do not re-grant.';

-- public.complete_game_session_side(target_session_id uuid)
CREATE OR REPLACE FUNCTION public.complete_game_session_side(target_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor record; s public.game_sessions%rowtype; required_count integer; answered_count integer;
  locked_at timestamptz;
begin
  select * into actor from private.m11a_actor_locked();
  -- One lock order for save/finalize/seen. Concurrent partner completions
  -- serialize here; the second one sets completed_at exactly once.
  select * into s from public.game_sessions
    where id = target_session_id and couple_id = actor.caller_couple for update;
  if s.id is null then raise exception using errcode = '42501', message = 'session unavailable'; end if;
  select completed_at into locked_at from public.game_session_sides
    where session_id = s.id and actor_role = actor.caller_role;
  if locked_at is not null then
    return private.m11a_session_state(s.id, actor.caller_couple, actor.caller_role);
  end if;
  select count(*), count(a.item_id) into required_count, answered_count
    from public.game_session_items i
    left join public.game_session_answers a on a.item_id = i.id and a.actor_role = actor.caller_role
    where i.session_id = s.id;
  if required_count = 0 or answered_count <> required_count then
    raise exception using errcode = '22023', message = 'answer required';
  end if;
  update public.game_session_sides set completed_at = now()
    where session_id = s.id and actor_role = actor.caller_role;
  if (select count(*) from public.game_session_sides side
      where side.session_id = s.id and side.completed_at is not null) = 2 then
    update public.game_sessions set completed_at = coalesce(completed_at, now()) where id = s.id;
  end if;
  return private.m11a_session_state(s.id, actor.caller_couple, actor.caller_role);
end;
$function$;

-- public.complete_left_for_you_cleanup(target_item_id uuid)
CREATE OR REPLACE FUNCTION public.complete_left_for_you_cleanup(target_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  completed_item private.left_for_you_cleanup_queue%rowtype;
begin
  update private.left_for_you_cleanup_queue
  set completed_at = now(), claimed_at = null
  where item_id = target_item_id
    and source_deleted_at is not null
    and completed_at is null
  returning * into completed_item;

  if completed_item.item_id is null then
    return jsonb_build_object('status', 'absent', 'item_id', target_item_id);
  end if;

  return jsonb_build_object('status', 'completed', 'item_id', target_item_id);
end;
$function$;

-- public.complete_partner_knowledge_deck(target_deck smallint, target_guesses jsonb)
CREATE OR REPLACE FUNCTION public.complete_partner_knowledge_deck(target_deck smallint, target_guesses jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid:=auth.uid(); cid uuid; pid uuid; partner_name text; ws date:=date_trunc('week',current_timestamp at time zone 'Europe/Rome')::date;
  required_count integer; valid_count integer; score_count integer; awarded integer; inserted_id uuid; stored public.partner_knowledge_attempts%rowtype; details jsonb;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  if target_deck not between 1 and 3 then raise exception 'Invalid deck'; end if;
  if jsonb_typeof(target_guesses)<>'object' then raise exception 'Invalid guesses'; end if;
  select couple_id into cid from public.profiles where id=uid;
  if cid is null then raise exception 'Profile not linked'; end if;
  select id,display_name into pid,partner_name from public.profiles where couple_id=cid and id<>uid limit 1;
  if pid is null then raise exception 'Partner not linked'; end if;
  select * into stored from public.partner_knowledge_attempts where couple_id=cid and user_id=uid and week_start=ws and deck=target_deck;
  if not found then
    with latest as (
      select distinct on(qr.question_id) qr.question_id,qr.answer_index from public.quiz_responses qr join public.quiz_sets qs on qs.id=qr.set_id where qr.user_id=pid and qr.couple_id=cid and qs.mode='match' order by qr.question_id,qr.updated_at desc
    ), ranked as (
      select q.id question_id,q.options,l.answer_index,row_number() over(order by md5(q.id::text||ws::text||uid::text)) rn from latest l join public.quiz_questions q on q.id=l.question_id
    ), selected as (
      select *,((rn-1)/5+1)::int deck from ranked where rn<=15
    )
    select count(*),count(*) filter(where target_guesses ? question_id::text and (target_guesses->>question_id::text) ~ '^[0-9]+$' and (target_guesses->>question_id::text)::int>=0 and (target_guesses->>question_id::text)::int<jsonb_array_length(options)),count(*) filter(where target_guesses ? question_id::text and (target_guesses->>question_id::text) ~ '^[0-9]+$' and (target_guesses->>question_id::text)::int=answer_index)
    into required_count,valid_count,score_count from selected where deck=target_deck;
    if required_count=0 then raise exception 'Knowledge deck unavailable'; end if;
    if valid_count<>required_count then raise exception 'Complete every answer first'; end if;
    awarded:=least(50,score_count*10);
    insert into public.partner_knowledge_attempts(couple_id,user_id,week_start,deck,guesses,score,xp_awarded) values(cid,uid,ws,target_deck,target_guesses,score_count,awarded) on conflict(couple_id,user_id,week_start,deck) do nothing returning id into inserted_id;
    if inserted_id is not null then
      update public.couples set bond_xp=coalesce(bond_xp,0)+awarded where id=cid;
      insert into public.activity(couple_id,actor_id,type,payload) values(cid,uid,'partner_knowledge_completed',jsonb_build_object('deck',target_deck,'partner_name',partner_name,'score',score_count,'xp',awarded));
    end if;
    select * into stored from public.partner_knowledge_attempts where couple_id=cid and user_id=uid and week_start=ws and deck=target_deck;
  end if;
  with latest as (
    select distinct on(qr.question_id) qr.question_id,qr.answer_index from public.quiz_responses qr join public.quiz_sets qs on qs.id=qr.set_id where qr.user_id=pid and qr.couple_id=cid and qs.mode='match' order by qr.question_id,qr.updated_at desc
  ), ranked as (
    select q.id question_id,q.question,q.options,l.answer_index,row_number() over(order by md5(q.id::text||ws::text||uid::text)) rn from latest l join public.quiz_questions q on q.id=l.question_id
  ), selected as (
    select *,((rn-1)/5+1)::int deck from ranked where rn<=15
  )
  select coalesce(jsonb_agg(jsonb_build_object('id',question_id,'question',question,'options',options,'your_answer',(stored.guesses->>question_id::text)::int,'partner_answer',answer_index,'correct',((stored.guesses->>question_id::text)::int=answer_index)) order by rn),'[]'::jsonb) into details from selected where deck=target_deck;
  return jsonb_build_object('completed',true,'partner_name',partner_name,'deck',target_deck,'score',stored.score,'xp_awarded',stored.xp_awarded,'reward_granted_now',inserted_id is not null,'questions',details);
end; $function$;
comment on function public.complete_partner_knowledge_deck(target_deck smallint, target_guesses jsonb) is 'RETIRED (US 2.0 F1B): Gioca v1 partner knowledge, no client caller since M11B. EXECUTE revoked from public/anon/authenticated.';

-- public.complete_shared_event(target_event_id uuid, target_occurrence_date date)
CREATE OR REPLACE FUNCTION public.complete_shared_event(target_event_id uuid, target_occurrence_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth'
AS $function$
declare
  uid uuid := auth.uid(); cid uuid; e public.shared_events%rowtype; existing public.shared_event_completions%rowtype;
  awarded integer; lead_days integer; today_rome date := (current_timestamp at time zone 'Europe/Rome')::date;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select couple_id into cid from public.profiles where id=uid;
  if cid is null then raise exception 'Profile not linked'; end if;
  select * into e from public.shared_events where id=target_event_id and couple_id=cid for update;
  if not found then raise exception 'Event not found'; end if;
  if target_occurrence_date is null or target_occurrence_date > today_rome then raise exception 'Event cannot be completed yet'; end if;
  if e.recurs_yearly then
    if extract(month from target_occurrence_date) <> extract(month from e.event_date) or extract(day from target_occurrence_date) <> extract(day from e.event_date) then raise exception 'Invalid recurring occurrence'; end if;
  elsif target_occurrence_date <> e.event_date then raise exception 'Invalid occurrence date'; end if;
  select * into existing from public.shared_event_completions where event_id=e.id and occurrence_date=target_occurrence_date;
  if found then return jsonb_build_object('completed',true,'already_completed',true,'xp_awarded',existing.xp_awarded,'completed_at',existing.completed_at); end if;
  lead_days := greatest(0, target_occurrence_date - (e.created_at at time zone 'Europe/Rome')::date);
  awarded := case when e.recurs_yearly then 60 when lead_days >= 7 then 50 when lead_days >= 2 then 35 else 25 end;
  insert into public.shared_event_completions(event_id,couple_id,occurrence_date,completed_by,xp_awarded) values(e.id,cid,target_occurrence_date,uid,awarded);
  update public.couples set bond_xp=coalesce(bond_xp,0)+awarded where id=cid;
  insert into public.activity(couple_id,actor_id,type,payload) values(cid,uid,'shared_event_completed',jsonb_build_object('event_id',e.id,'title',e.title,'occurrence_date',target_occurrence_date,'xp',awarded));
  return jsonb_build_object('completed',true,'already_completed',false,'xp_awarded',awarded,'occurrence_date',target_occurrence_date);
end; $function$;

-- public.confirm_bond_quest(target_quest_id uuid)
CREATE OR REPLACE FUNCTION public.confirm_bond_quest(target_quest_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  select private.confirm_bond_quest_internal(target_quest_id)
$function$;

-- public.confirm_bucket_item_lived(p_item_id uuid)
CREATE OR REPLACE FUNCTION public.confirm_bucket_item_lived(p_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_item public.bucket_items%rowtype;
  v_seen_proposer uuid;
  v_seen_couple uuid;
  v_ids uuid[];
  v_lock record;
  v_caller_couple uuid;
  v_proposer_couple uuid;
  v_proposer_is_member boolean := false;
begin
  if v_uid is null then
    raise exception using errcode = '42501', message = 'bucket_items_lived_requires_authenticated_member';
  end if;

  -- Strategia di lock (stesso ordine del flusso claim_us_role, che blocca il
  -- profilo PRIMA delle righe bucket_items: profili -> riga, mai il contrario,
  -- quindi nessun deadlock con il re-pair):
  --   1. lettura SENZA lock della riga, solo per sapere coppia e proponente;
  --   2. lock FOR SHARE dei profili coinvolti (chi chiama + proponente), in
  --      ordine deterministico per id: un re-pair/rimozione (che li blocca
  --      FOR UPDATE o li cancella) aspetta la fine di questa transazione, e
  --      chi è già stato rimosso non si vede più (la lettura sotto lock è
  --      quella corrente, non quella di prima dell'attesa);
  --   3. lock FOR UPDATE della riga e RIVERIFICA dopo l'attesa: coppia e
  --      proponente devono essere ancora quelli su cui abbiamo bloccato i
  --      profili, altrimenti 40001 (retry sicuro: la RPC è idempotente).
  select b.couple_id, b.lived_proposed_by into v_seen_couple, v_seen_proposer
  from public.bucket_items b where b.id = p_item_id;
  -- Stesso errore per "non esiste" e "è di un'altra coppia": la RPC non
  -- rivela l'esistenza di righe fuori dalla coppia di chi chiama.
  if not found then
    raise exception using errcode = 'P0002', message = 'bucket_items_not_found';
  end if;

  v_ids := array[v_uid];
  if v_seen_proposer is not null and v_seen_proposer <> v_uid then
    v_ids := v_ids || v_seen_proposer;
  end if;

  for v_lock in
    select p.id, p.couple_id from public.profiles p
    where p.id = any(v_ids)
    order by p.id
    for share
  loop
    if v_lock.id = v_uid then v_caller_couple := v_lock.couple_id; end if;
    if v_lock.id = v_seen_proposer then v_proposer_couple := v_lock.couple_id; end if;
  end loop;

  if v_caller_couple is null then
    raise exception using errcode = '42501', message = 'bucket_items_lived_requires_authenticated_member';
  end if;
  if v_caller_couple <> v_seen_couple then
    raise exception using errcode = 'P0002', message = 'bucket_items_not_found';
  end if;

  select b.* into v_item from public.bucket_items b where b.id = p_item_id for update;
  if not found or v_item.couple_id <> v_caller_couple then
    raise exception using errcode = 'P0002', message = 'bucket_items_not_found';
  end if;
  if v_item.lived_proposed_by is distinct from v_seen_proposer then
    raise exception using errcode = '40001', message = 'bucket_items_lived_proposal_changed_retry';
  end if;

  if v_item.status not in ('idea', 'scheduled', 'lived') then
    raise exception using errcode = '22023', message = format('bucket_items_lived_not_allowed_from: %s', v_item.status);
  end if;

  if v_item.status <> 'lived' then
    -- Il proponente vale solo se è ANCORA membro della stessa coppia (letto
    -- sotto lock: non può cambiare fino al commit).
    v_proposer_is_member := v_item.lived_proposed_by is not null
      and v_item.lived_proposed_by <> v_uid
      and v_proposer_couple is not distinct from v_item.couple_id;

    perform set_config('us.bucket_items_lived_confirm', 'on', true);
    if v_item.lived_proposed_by is null
       or (v_item.lived_proposed_by <> v_uid and not v_proposer_is_member) then
      update public.bucket_items
        set lived_proposed_by = v_uid, lived_proposed_at = now()
        where id = p_item_id;
    elsif v_item.lived_proposed_by <> v_uid then
      update public.bucket_items set status = 'lived' where id = p_item_id;
    end if;
    perform set_config('us.bucket_items_lived_confirm', 'off', true);
  end if;

  select b.* into v_item from public.bucket_items b where b.id = p_item_id;
  return jsonb_build_object(
    'id', v_item.id,
    'status', v_item.status,
    'calendar_entry_id', v_item.calendar_entry_id,
    'completed', v_item.completed,
    'completed_at', v_item.completed_at,
    'lived_proposed_by', v_item.lived_proposed_by,
    'lived_proposed_at', v_item.lived_proposed_at
  );
end;
$function$;

-- public.conserve_left_for_you(target_item_id uuid)
CREATE OR REPLACE FUNCTION public.conserve_left_for_you(target_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_item public.left_for_you%rowtype;
  existing_row public.conserva_contributions%rowtype;
  created_row public.conserva_contributions%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'authentication required';
  end if;

  select entry.* into target_item
  from public.left_for_you as entry
  where entry.id = target_item_id
    and entry.couple_id = private.current_couple_id()
    and entry.recipient_id = auth.uid()
  for update;

  if target_item.id is null then
    raise exception using errcode = '42501', message = 'conserva_recipient_required';
  end if;

  insert into public.conserva_contributions as c
    (couple_id, source_item_id, source_sender_id, conserved_by)
  values
    (target_item.couple_id, target_item.id, target_item.sender_id, auth.uid())
  on conflict (source_item_id) do nothing
  returning c.* into created_row;

  if created_row.id is not null then
    return jsonb_build_object(
      'id', created_row.id,
      'status', 'created',
      'couple_id', created_row.couple_id,
      'source_item_id', created_row.source_item_id,
      'source_sender_id', created_row.source_sender_id,
      'conserved_by', created_row.conserved_by,
      'created_at', created_row.created_at
    );
  end if;

  select e.* into existing_row
  from public.conserva_contributions as e
  where e.source_item_id = target_item.id;

  return jsonb_build_object(
    'id', existing_row.id,
    'status', 'existing',
    'couple_id', existing_row.couple_id,
    'source_item_id', existing_row.source_item_id,
    'source_sender_id', existing_row.source_sender_id,
    'conserved_by', existing_row.conserved_by,
    'created_at', existing_row.created_at
  );
end;
$function$;

-- public.create_couple_question(request_id uuid, question_text text, answer_kind text, options jsonb)
CREATE OR REPLACE FUNCTION public.create_couple_question(request_id uuid, question_text text, answer_kind text, options jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor record; normalized jsonb; q public.couple_questions%rowtype;
begin
  select * into actor from private.m11a_actor_locked();
  if request_id is null then raise exception using errcode = '22023', message = 'request id required'; end if;
  normalized := private.m11a_valid_options(answer_kind, question_text, options);
  insert into public.couple_questions(couple_id, author_role, create_request_id, question_text, answer_kind, options)
  values (actor.caller_couple, actor.caller_role, request_id, btrim(question_text), answer_kind, normalized)
  on conflict (couple_id, author_role, create_request_id) do nothing returning * into q;
  if q.id is null then
    select * into q from public.couple_questions
    where couple_id = actor.caller_couple and author_role = actor.caller_role and create_request_id = request_id;
    if q.question_text <> btrim(question_text) or q.answer_kind <> answer_kind or q.options <> normalized then
      raise exception using errcode = '22023', message = 'request already used';
    end if;
  end if;
  return private.m11a_question_json(q);
end;
$function$;

-- public.create_weekly_question(request_id uuid, question_text text, answer_kind text, options jsonb, families text[])
CREATE OR REPLACE FUNCTION public.create_weekly_question(request_id uuid, question_text text, answer_kind text, options jsonb, families text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor record; normalized jsonb; cleaned_families text[]; week date; existing public.couple_questions%rowtype;
  at_time timestamptz := private.game_v2_clock();
begin
  select * into actor from private.m11a_actor_locked();
  if request_id is null then raise exception using errcode = '22023', message = 'request id required'; end if;
  normalized := private.m11a_valid_options(answer_kind, question_text, options);
  cleaned_families := private.game_v2_valid_families(families, answer_kind);
  -- Serialize every weekly write of the couple (double taps, both partners,
  -- a retry racing its original); the partial unique index stays the final
  -- authority.
  perform pg_advisory_xact_lock(hashtextextended('game_v2_weekly:' || actor.caller_couple::text, 0));

  select * into existing from public.couple_questions q
    where q.couple_id = actor.caller_couple and q.author_role = actor.caller_role
      and q.create_request_id = create_weekly_question.request_id;
  if existing.id is not null then
    if existing.origin <> 'weekly' or existing.question_text <> btrim(create_weekly_question.question_text)
      or existing.answer_kind <> create_weekly_question.answer_kind or existing.options <> normalized
      or existing.families <> cleaned_families then
      raise exception using errcode = '22023', message = 'request already used';
    end if;
    return private.game_v2_weekly_state(actor.caller_couple, actor.caller_role, at_time)
      || jsonb_build_object('question_id', existing.id, 'replayed', true);
  end if;

  week := private.game_v2_week_start(at_time);
  if private.game_v2_weekly_role(week) <> actor.caller_role then
    raise exception using errcode = '42501', message = 'not your turn';
  end if;
  if exists (select 1 from public.couple_questions q
      where q.couple_id = actor.caller_couple and q.origin = 'weekly' and q.week_start = week) then
    raise exception using errcode = '23505', message = 'weekly question already created';
  end if;
  insert into public.couple_questions(couple_id, author_role, create_request_id, question_text,
    answer_kind, options, origin, week_start, families)
  values (actor.caller_couple, actor.caller_role, create_weekly_question.request_id,
    btrim(create_weekly_question.question_text), create_weekly_question.answer_kind, normalized,
    'weekly', week, cleaned_families)
  returning * into existing;
  return private.game_v2_weekly_state(actor.caller_couple, actor.caller_role, at_time)
    || jsonb_build_object('question_id', existing.id, 'replayed', false);
end;
$function$;

-- public.delete_daily_question_outcome(target_question_id uuid, expected_revision integer)
CREATE OR REPLACE FUNCTION public.delete_daily_question_outcome(target_question_id uuid, expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_couple uuid;
  actor_role text;
  existing public.daily_question_outcomes%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'authentication required';
  end if;

  select profile.couple_id, profile.role
    into current_couple, actor_role
    from public.profiles as profile
   where profile.id = auth.uid()
     and profile.couple_id is not null;

  if current_couple is null or actor_role not in ('francesco', 'beatrice') then
    raise exception using errcode = '42501', message = 'couple membership required';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(current_couple::text || ':' || target_question_id::text || ':' || actor_role, 0)
  );

  select *
    into existing
    from public.daily_question_outcomes as outcome
   where outcome.couple_id = current_couple
     and outcome.question_id = target_question_id
     and outcome.author_role = actor_role
   for update;

  if existing.id is null then
    return jsonb_build_object('status', 'already_absent');
  end if;

  if expected_revision is null or expected_revision <> existing.revision then
    return jsonb_build_object('status', 'stale', 'id', existing.id, 'revision', existing.revision);
  end if;

  delete from public.daily_question_outcomes where id = existing.id;
  return jsonb_build_object('status', 'deleted', 'id', existing.id, 'revision', existing.revision);
end;
$function$;

-- public.delete_think_reaction(target_message_id uuid)
CREATE OR REPLACE FUNCTION public.delete_think_reaction(target_message_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_couple uuid;
  message public.shared_messages%rowtype;
  deleted_id uuid;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'authentication required';
  end if;

  current_couple := private.current_couple_id();
  select * into message
    from public.shared_messages
   where id = target_message_id
     and kind = 'think'
     and couple_id = current_couple
     and recipient_id = auth.uid()
   for update;
  if message.id is null then
    raise exception using errcode = '42501', message = 'think recipient required';
  end if;

  delete from public.think_reactions
   where message_id = target_message_id
  returning id into deleted_id;

  return jsonb_build_object('status', case when deleted_id is null then 'already_absent' else 'deleted' end, 'message_id', target_message_id);
end;
$function$;

-- public.dismiss_daily_reveal_notice(target_question_id uuid)
CREATE OR REPLACE FUNCTION public.dismiss_daily_reveal_notice(target_question_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  ctx record;
begin
  select * into ctx from private.daily_reveal_context(target_question_id);
  if not ctx.ready then
    raise exception using errcode = '42501', message = 'daily question reveal is not ready';
  end if;

  insert into public.daily_question_reveal_states as state (couple_id, question_id, actor_role, notice_dismissed_at)
  values (ctx.caller_couple, target_question_id, ctx.caller_role, now())
  on conflict (couple_id, question_id, actor_role) do update
    set notice_dismissed_at = coalesce(state.notice_dismissed_at, excluded.notice_dismissed_at),
        updated_at = now();

  return private.daily_reveal_meta(target_question_id, ctx.caller_couple, ctx.caller_role, true);
end;
$function$;
comment on function public.dismiss_daily_reveal_notice(target_question_id uuid) is 'M10.2: caller hides the Oggi "Risposte pronte" notice. Idempotent; does NOT mark the reveal as seen.';

