-- public.get_notification_preferences()
CREATE OR REPLACE FUNCTION public.get_notification_preferences()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid := auth.uid();
  prefs public.notification_preferences%rowtype;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select * into prefs from public.notification_preferences where user_id = uid;
  if not found then
    insert into public.notification_preferences(user_id) values(uid)
    on conflict(user_id) do nothing;
    select * into prefs from public.notification_preferences where user_id = uid;
  end if;
  return jsonb_build_object(
    'think', prefs.think,
    'today', prefs.today,
    'bond', prefs.bond,
    'relationship', prefs.relationship,
    'left_for_you', prefs.left_for_you,
    'games', prefs.games
  );
end;
$function$;

-- public.get_or_create_daily_question()
CREATE OR REPLACE FUNCTION public.get_or_create_daily_question()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  today date := private.daily_question_day(now());
  question_row public.daily_questions%rowtype;
  question_theme text;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'authentication required';
  end if;

  if not exists (
    select 1 from public.profiles as profile
     where profile.id = auth.uid()
       and profile.couple_id is not null
  ) then
    raise exception using errcode = '42501', message = 'couple membership required';
  end if;

  question_row := private.materialize_daily_question(today);

  select t.theme into question_theme
    from public.daily_question_templates as t
   where t.id = question_row.template_id;

  return jsonb_build_object(
    'id', question_row.id,
    'question', question_row.question,
    'question_date', question_row.question_date,
    'theme', question_theme,
    'day_timezone', 'Europe/Rome'
  );
end;
$function$;
comment on function public.get_or_create_daily_question() is 'M9E: today''s concrete Daily Question (Europe/Rome day), materialized once from the template bank if missing. Reveal stays with public.get_daily_state.';

-- public.get_partner_knowledge_hub()
CREATE OR REPLACE FUNCTION public.get_partner_knowledge_hub()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid:=auth.uid(); cid uuid; pid uuid; partner_name text; ws date:=date_trunc('week',current_timestamp at time zone 'Europe/Rome')::date; decks jsonb;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select couple_id into cid from public.profiles where id=uid;
  if cid is null then raise exception 'Profile not linked'; end if;
  select id,display_name into pid,partner_name from public.profiles where couple_id=cid and id<>uid limit 1;
  if pid is null then raise exception 'Partner not linked'; end if;
  with latest as (
    select distinct on(qr.question_id) qr.question_id,qr.answer_index
    from public.quiz_responses qr join public.quiz_sets qs on qs.id=qr.set_id
    where qr.user_id=pid and qr.couple_id=cid and qs.mode='match'
    order by qr.question_id,qr.updated_at desc
  ), ranked as (
    select q.id question_id,q.question,q.options,row_number() over(order by md5(q.id::text||ws::text||uid::text)) rn
    from latest l join public.quiz_questions q on q.id=l.question_id
  ), selected as (
    select *,((rn-1)/5+1)::int deck from ranked where rn<=15
  ), deck_rows as (
    select s.deck,jsonb_agg(jsonb_build_object('id',s.question_id,'question',s.question,'options',s.options) order by s.rn) questions,count(*) cnt
    from selected s group by s.deck
  )
  select coalesce(jsonb_agg(jsonb_build_object('deck',d.deck,'questions',d.questions,'count',d.cnt,'completed',a.id is not null,'score',a.score,'xp_awarded',a.xp_awarded) order by d.deck),'[]'::jsonb)
  into decks
  from deck_rows d left join public.partner_knowledge_attempts a on a.couple_id=cid and a.user_id=uid and a.week_start=ws and a.deck=d.deck;
  return jsonb_build_object('week_start',ws,'next_refresh',ws+7,'partner_name',partner_name,'decks',decks);
end; $function$;
comment on function public.get_partner_knowledge_hub() is 'RETIRED (US 2.0 F1B): Gioca v1 partner knowledge, no client caller since M11B. EXECUTE revoked from public/anon/authenticated.';

-- public.get_progression_v1()
CREATE OR REPLACE FUNCTION public.get_progression_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  uid uuid := auth.uid();
  cid uuid;
  total integer;
  level_data jsonb;
  today_rome date := (now() at time zone 'Europe/Rome')::date;
  last_day date;
  rhythm integer := 0;
  rewards jsonb := '[]'::jsonb;
  pending jsonb := '[]'::jsonb;
  next_reward jsonb;
  prefs public.couple_progression_preferences%rowtype;
  slots jsonb;
begin
  if uid is null then
    raise exception using errcode = '42501', message = 'authentication required';
  end if;
  select p.couple_id into cid from public.profiles p where p.id = uid;
  if cid is null then
    raise exception using errcode = '42501', message = 'couple membership required';
  end if;

  select coalesce(c.bond_xp, 0) into total from public.couples c where c.id = cid;
  if total is null then
    raise exception using errcode = 'P0002', message = 'couple not found';
  end if;
  perform private.progression_sync_unlocks(cid, total);
  level_data := private.progression_level_info(total);

  select pref.* into prefs from public.couple_progression_preferences pref where pref.couple_id = cid;
  slots := jsonb_build_object(
    'frame', prefs.frame_reward_id,
    'theme', prefs.theme_reward_id,
    'accent', prefs.accent_reward_id,
    'effect', prefs.effect_reward_id,
    'badge', prefs.badge_reward_id,
    'sticker', prefs.sticker_reward_id,
    'ring', prefs.ring_reward_id
  );

  select max(e.action_day) into last_day
    from public.progression_events e
   where e.couple_id = cid and e.counts_rhythm = true and e.action_day <= today_rome;

  if last_day is not null and last_day >= today_rome - 1 then
    with days as (
      select distinct e.action_day
        from public.progression_events e
       where e.couple_id = cid and e.counts_rhythm = true and e.action_day <= last_day
    ), ranked as (
      select d.action_day, row_number() over(order by d.action_day desc) as rn from days d
    )
    select count(*)::integer into rhythm
      from ranked r
     where r.action_day = last_day - ((r.rn - 1)::integer);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', reward.id,
      'level_required', reward.level_required,
      'category', reward.category,
      'title', reward.title,
      'description', reward.description,
      'token', reward.token,
      'unlocked', unlock.reward_id is not null,
      'equipped', unlock.reward_id is not null and (slots ->> reward.category) = reward.id
    ) order by reward.sort_order), '[]'::jsonb)
    into rewards
    from public.progression_reward_catalog reward
    left join public.couple_reward_unlocks unlock
      on unlock.couple_id = cid and unlock.reward_id = reward.id
   where reward.active = true;

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', reward.id,
      'level_required', reward.level_required,
      'category', reward.category,
      'title', reward.title,
      'description', reward.description,
      'token', reward.token
    ) order by reward.sort_order), '[]'::jsonb)
    into pending
    from public.progression_reward_catalog reward
    join public.couple_reward_unlocks unlock
      on unlock.couple_id = cid and unlock.reward_id = reward.id
    left join public.progression_reward_views seen
      on seen.couple_id = cid and seen.reward_id = reward.id and seen.profile_id = uid
   where reward.active = true and reward.announce = true and seen.reward_id is null;

  select jsonb_build_object(
      'id', reward.id,
      'level_required', reward.level_required,
      'category', reward.category,
      'title', reward.title,
      'description', reward.description,
      'token', reward.token
    )
    into next_reward
    from public.progression_reward_catalog reward
   where reward.active = true
     and reward.level_required > private.progression_level(total)
   order by reward.level_required, reward.sort_order
   limit 1;

  return jsonb_build_object(
    'total_xp', total,
    'level', (level_data->>'level')::integer,
    'current_xp', (level_data->>'current_xp')::integer,
    'needed_xp', (level_data->>'needed_xp')::integer,
    'remaining_xp', (level_data->>'remaining_xp')::integer,
    'progress', (level_data->>'progress')::numeric,
    'rhythm_days', coalesce(rhythm, 0),
    'rhythm_today', exists(
      select 1 from public.progression_events e
       where e.couple_id = cid and e.counts_rhythm = true and e.action_day = today_rome
    ),
    'today', today_rome,
    'rewards', rewards,
    'pending_unlocks', pending,
    'next_reward', next_reward,
    'preferences', jsonb_build_object(
      'frame_reward_id', prefs.frame_reward_id,
      'theme_reward_id', prefs.theme_reward_id,
      'accent_reward_id', prefs.accent_reward_id,
      'effect_reward_id', prefs.effect_reward_id,
      'badge_reward_id', prefs.badge_reward_id,
      'sticker_reward_id', prefs.sticker_reward_id,
      'ring_reward_id', prefs.ring_reward_id
    )
  );
end;
$function$;

-- public.get_quiz_state(target_set_id uuid)
CREATE OR REPLACE FUNCTION public.get_quiz_state(target_set_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid := auth.uid(); cid uuid; ws date := date_trunc('week', current_timestamp at time zone 'Europe/Rome')::date;
  total_count integer:=0; my_count integer:=0; partner_count integer:=0; score integer:=null;
  my_answers jsonb:='{}'::jsonb; partner_answers jsonb:=null; reward_xp integer:=null; inserted_xp integer:=null; reward_granted_now boolean:=false; set_mode text:='match';
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select couple_id into cid from public.profiles where id=uid;
  if cid is null then raise exception 'Profile not linked'; end if;
  select coalesce(mode,'match') into set_mode from public.quiz_sets where id=target_set_id;
  if set_mode is null then raise exception 'Quiz set not found'; end if;
  select count(*) into total_count from public.quiz_questions where set_id=target_set_id;
  if total_count=0 then raise exception 'Quiz set not found or empty'; end if;
  select count(*),coalesce(jsonb_object_agg(question_id::text,answer_index),'{}'::jsonb) into my_count,my_answers from public.quiz_responses where set_id=target_set_id and couple_id=cid and user_id=uid and week_start=ws;
  select count(*) into partner_count from public.quiz_responses where set_id=target_set_id and couple_id=cid and user_id<>uid and week_start=ws;
  if my_count>=total_count and partner_count>=total_count then
    select coalesce(jsonb_object_agg(question_id::text,answer_index),'{}'::jsonb) into partner_answers from public.quiz_responses where set_id=target_set_id and couple_id=cid and user_id<>uid and week_start=ws;
    select count(*) into score from public.quiz_responses mine join public.quiz_responses partner on partner.question_id=mine.question_id and partner.set_id=mine.set_id and partner.couple_id=mine.couple_id and partner.week_start=mine.week_start and partner.user_id<>mine.user_id where mine.set_id=target_set_id and mine.couple_id=cid and mine.user_id=uid and mine.week_start=ws and mine.answer_index=partner.answer_index;
    reward_xp := case when set_mode='match' then score*5 else 20+score*3 end;
    insert into public.weekly_quiz_rewards(couple_id,set_id,week_start,score,xp_awarded) values(cid,target_set_id,ws,score,reward_xp) on conflict(couple_id,set_id,week_start) do nothing returning xp_awarded into inserted_xp;
    if inserted_xp is not null then update public.couples set bond_xp=coalesce(bond_xp,0)+inserted_xp where id=cid; reward_granted_now:=true; end if;
    select xp_awarded into reward_xp from public.weekly_quiz_rewards where couple_id=cid and set_id=target_set_id and week_start=ws;
  end if;
  return jsonb_build_object('mode',set_mode,'total',total_count,'my_count',my_count,'partner_count',partner_count,'my_complete',my_count>=total_count,'partner_complete',partner_count>=total_count,'both_complete',my_count>=total_count and partner_count>=total_count,'my_answers',my_answers,'partner_answers',partner_answers,'score',score,'week_start',ws,'xp_awarded',reward_xp,'reward_granted_now',reward_granted_now);
end; $function$;
comment on function public.get_quiz_state(target_set_id uuid) is 'RETIRED (US 2.0 F1B): Gioca v1, no client caller since M11B. EXECUTE revoked from public/anon/authenticated.';

