-- public.get_weekly_quiz_sets()
CREATE OR REPLACE FUNCTION public.get_weekly_quiz_sets()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); cid uuid; ws date := date_trunc('week', current_timestamp at time zone 'Europe/Rome')::date; week_index integer := ((ws - date '2026-08-17') / 7)::integer; result jsonb;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select couple_id into cid from public.profiles where id=uid;
  if cid is null then raise exception 'Profile not linked'; end if;
  with ranked as (
    select id,slug,title,category,row_number() over(order by md5(slug))-1 rn,count(*) over() cnt from public.quiz_sets where mode='match'
  ), positioned as (
    select id,slug,title,category,cnt,mod((rn-mod(week_index*3,cnt)+cnt),cnt) pos from ranked
  ), chosen as (
    select id,slug,title,category,pos from positioned where pos<least(3,cnt) order by pos
  )
  select jsonb_build_object('week_start',ws,'next_refresh',ws+7,'sets',coalesce(jsonb_agg(jsonb_build_object('id',id,'slug',slug,'title',title,'category',category,'mode','match') order by pos),'[]'::jsonb)) into result from chosen;
  return result;
end; $function$;
comment on function public.get_weekly_quiz_sets() is 'RETIRED (US 2.0 F1B): Gioca v1, no client caller since M11B. EXECUTE revoked from public/anon/authenticated.';

-- public.keep_daily_question(target_question_id uuid)
CREATE OR REPLACE FUNCTION public.keep_daily_question(target_question_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor record;
  question public.daily_questions%rowtype;
  kept public.daily_question_keepsakes%rowtype;
  daily_state jsonb;
  mine text;
  theirs text;
  opened_at timestamptz;
begin
  select * into actor from private.m11a_actor_locked();
  if target_question_id is null then
    raise exception using errcode = '22004', message = 'daily_question_id_required';
  end if;

  -- Retry / reconnect / double tap: the kept row answers as it is.
  select k.* into kept from public.daily_question_keepsakes k
    where k.couple_id = actor.caller_couple and k.question_id = target_question_id;
  if found then
    return private.daily_question_keepsake_json(kept, 'existing');
  end if;

  select q.* into question from public.daily_questions q where q.id = target_question_id;
  if not found then
    raise exception using errcode = 'P0002', message = 'daily_question_not_found';
  end if;

  -- The reveal authority decides. Nothing is read before both_answered.
  daily_state := public.get_daily_state(target_question_id);
  if not coalesce((daily_state->>'both_answered')::boolean, false) then
    raise exception using errcode = '42501', message = 'daily_question_reveal_not_ready';
  end if;
  mine := daily_state->>'my_answer';
  theirs := daily_state->>'partner_answer';
  if mine is null or theirs is null then
    raise exception using errcode = '55000', message = 'daily_question_answers_unavailable';
  end if;

  select max(a.created_at) into opened_at from public.daily_answers a
    where a.question_id = target_question_id and a.couple_id = actor.caller_couple;

  -- Both partners may keep at the same moment: serialize per couple + Daily.
  perform pg_advisory_xact_lock(hashtextextended(
    'us:daily_keepsake:' || actor.caller_couple::text || ':' || target_question_id::text, 0));

  insert into public.daily_question_keepsakes (couple_id, question_id, question_text, question_date,
    francesco_answer, beatrice_answer, revealed_at, kept_by_role)
  values (actor.caller_couple, target_question_id, left(question.question, 500), question.question_date,
    case when actor.caller_role = 'francesco' then mine else theirs end,
    case when actor.caller_role = 'beatrice' then mine else theirs end,
    coalesce(opened_at, now()), actor.caller_role)
  on conflict (couple_id, question_id) do nothing
  returning * into kept;

  if kept.id is null then
    -- The other partner (or an earlier tap) won; it is committed by now.
    select k.* into kept from public.daily_question_keepsakes k
      where k.couple_id = actor.caller_couple and k.question_id = target_question_id;
    return private.daily_question_keepsake_json(kept, 'existing');
  end if;

  return private.daily_question_keepsake_json(kept, 'kept');
end;
$function$;
comment on function public.keep_daily_question(target_question_id uuid) is 'M12B.4: keep the revealed Daily exchange of the caller''s couple (Conserva). Refuses before get_daily_state.both_answered; idempotent per couple + question; returns status kept|existing, never answer text.';

-- public.link_moment_to_source(target_moment_id uuid, source_kind text, source_ref uuid)
CREATE OR REPLACE FUNCTION public.link_moment_to_source(target_moment_id uuid, source_kind text, source_ref uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor record;
  target public.moments%rowtype;
  completion record;
  item record;
  snap_title text;
  snap_date date;
  link_row public.living_provenance%rowtype;
begin
  select * into actor from private.m11a_actor_locked();
  if target_moment_id is null or source_ref is null or source_kind is null then
    raise exception using errcode = '22004', message = 'living_provenance_arguments_required';
  end if;
  if source_kind not in ('shared_event_completion', 'da_vivere') then
    raise exception using errcode = '22023', message = 'living_provenance_unsupported_source_kind';
  end if;

  -- Same error for "does not exist" and "belongs to another couple".
  select m.* into target from public.moments m
    where m.id = link_moment_to_source.target_moment_id and m.couple_id = actor.caller_couple;
  if not found then
    raise exception using errcode = 'P0002', message = 'living_provenance_moment_not_found';
  end if;
  if target.created_by is distinct from auth.uid() then
    raise exception using errcode = '42501', message = 'living_provenance_moment_not_own';
  end if;

  if source_kind = 'shared_event_completion' then
    select c.id, c.occurrence_date, coalesce(c.event_title_snapshot, e.title) as title into completion
      from public.shared_event_completions c
      left join public.shared_events e on e.id = c.event_id and e.couple_id = c.couple_id
      where c.id = link_moment_to_source.source_ref and c.couple_id = actor.caller_couple;
    if not found then
      raise exception using errcode = 'P0002', message = 'living_provenance_source_not_found';
    end if;
    snap_title := completion.title;
    snap_date := completion.occurrence_date;
  else
    select b.id, b.title, b.completed_at,
        coalesce((ce.starts_at at time zone 'Europe/Rome')::date, ce.start_date,
          (b.completed_at at time zone 'Europe/Rome')::date) as lived_on
      into item
      from public.bucket_items b
      left join public.calendar_entries ce on ce.id = b.calendar_entry_id and ce.couple_id = b.couple_id
      where b.id = link_moment_to_source.source_ref and b.couple_id = actor.caller_couple;
    if not found then
      raise exception using errcode = 'P0002', message = 'living_provenance_source_not_found';
    end if;
    -- Lived means confirmed by both (M7D); completed_at is server-owned and
    -- survives lived -> archived. Scheduled or abandoned ideas are refused.
    if item.completed_at is null then
      raise exception using errcode = '22023', message = 'living_provenance_source_not_lived';
    end if;
    snap_title := item.title;
    snap_date := item.lived_on;
  end if;

  insert into public.living_provenance (couple_id, source_kind, source_ref,
    source_event_completion_id, source_bucket_item_id, source_title, source_date,
    target_kind, target_ref, target_moment_id, linked_by_role)
  values (actor.caller_couple, link_moment_to_source.source_kind, link_moment_to_source.source_ref,
    case when link_moment_to_source.source_kind = 'shared_event_completion' then link_moment_to_source.source_ref end,
    case when link_moment_to_source.source_kind = 'da_vivere' then link_moment_to_source.source_ref end,
    left(snap_title, 200), snap_date,
    'moment', link_moment_to_source.target_moment_id, link_moment_to_source.target_moment_id, actor.caller_role)
  on conflict do nothing
  returning * into link_row;

  if link_row.id is null then
    -- A concurrent or earlier link won; it is committed by now.
    select p.* into link_row from public.living_provenance p
      where p.target_kind = 'moment' and p.target_ref = link_moment_to_source.target_moment_id;
    if found then
      if link_row.source_kind = link_moment_to_source.source_kind and link_row.source_ref = link_moment_to_source.source_ref then
        return jsonb_build_object('status', 'existing', 'id', link_row.id, 'source_key', link_row.source_key,
          'moment_id', link_row.target_ref, 'source_title', link_row.source_title, 'source_date', link_row.source_date);
      end if;
      raise exception using errcode = '23505', message = 'living_provenance_moment_already_linked';
    end if;
    raise exception using errcode = '23505', message = 'living_provenance_source_already_kept';
  end if;

  return jsonb_build_object('status', 'linked', 'id', link_row.id, 'source_key', link_row.source_key,
    'moment_id', link_row.target_ref, 'source_title', link_row.source_title, 'source_date', link_row.source_date);
end;
$function$;

-- public.list_couple_questions()
CREATE OR REPLACE FUNCTION public.list_couple_questions()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor record; result jsonb;
begin
  select * into actor from private.m11a_actor();
  select coalesce(jsonb_agg(
      case when private.game_v2_question_sealed(q.id, q.origin, q.author_role, actor.caller_role)
        then jsonb_build_object('id', q.id, 'sealed', true, 'origin', q.origin,
          'author_role', q.author_role, 'week_start', q.week_start, 'created_at', q.created_at)
        else private.m11a_question_json(q) || jsonb_build_object('sealed', false, 'origin', q.origin,
          'week_start', q.week_start, 'families', to_jsonb(q.families))
      end order by q.created_at desc, q.id desc), '[]'::jsonb)
    into result from public.couple_questions q
    where q.couple_id = actor.caller_couple and q.archived_at is null;
  return result;
end;
$function$;
comment on function public.list_couple_questions() is 'RETIRED (US 2.0 F1B): M11A, superseded by Game V2. EXECUTE revoked from public/anon/authenticated.';

-- public.list_game_sessions()
CREATE OR REPLACE FUNCTION public.list_game_sessions()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor record; result jsonb;
begin
  select * into actor from private.m11a_actor();
  select coalesce(jsonb_agg(row_data.data order by row_data.started_at desc, row_data.id desc), '[]'::jsonb)
    into result from (
      select s.id, s.started_at, private.game_v2_session_summary(s.id, actor.caller_couple, actor.caller_role)
        || jsonb_build_object('content_source', s.content_source, 'question_preview', first_item.question_text) data
      from public.game_sessions s
      left join lateral (select i.question_text from public.game_session_items i
        where i.session_id = s.id order by i.position limit 1) first_item on true
      where s.couple_id = actor.caller_couple
      order by s.started_at desc, s.id desc limit 50
    ) row_data;
  return result;
end;
$function$;
comment on function public.list_game_sessions() is 'RETIRED (US 2.0 F1B): M11A, superseded by Game V2. EXECUTE revoked from public/anon/authenticated.';

-- public.mark_daily_reveal_seen(target_question_id uuid)
CREATE OR REPLACE FUNCTION public.mark_daily_reveal_seen(target_question_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  ctx record;
begin
  select * into ctx from private.daily_reveal_context(target_question_id);
  if not ctx.ready then
    raise exception using errcode = '42501', message = 'daily question reveal is not ready';
  end if;

  insert into public.daily_question_reveal_states as state (couple_id, question_id, actor_role, reveal_seen_at)
  values (ctx.caller_couple, target_question_id, ctx.caller_role, now())
  on conflict (couple_id, question_id, actor_role) do update
    set reveal_seen_at = coalesce(state.reveal_seen_at, excluded.reveal_seen_at),
        updated_at = now();

  return private.daily_reveal_meta(target_question_id, ctx.caller_couple, ctx.caller_role, true);
end;
$function$;
comment on function public.mark_daily_reveal_seen(target_question_id uuid) is 'M10.2: caller opened the reveal. Idempotent; requires both answered; independent from dismiss.';

-- public.mark_game_session_reveal_seen(target_session_id uuid)
CREATE OR REPLACE FUNCTION public.mark_game_session_reveal_seen(target_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor record; s public.game_sessions%rowtype;
begin
  select * into actor from private.m11a_actor_locked();
  select * into s from public.game_sessions
    where id = target_session_id and couple_id = actor.caller_couple for update;
  if s.id is null then raise exception using errcode = '42501', message = 'session unavailable'; end if;
  if s.completed_at is null then raise exception using errcode = '42501', message = 'reveal not ready'; end if;
  update public.game_session_sides set reveal_seen_at = coalesce(reveal_seen_at, now())
    where session_id = s.id and actor_role = actor.caller_role;
  return private.m11a_session_state(s.id, actor.caller_couple, actor.caller_role);
end;
$function$;

-- public.mark_left_item_seen(target_item_id uuid)
CREATE OR REPLACE FUNCTION public.mark_left_item_seen(target_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_item public.left_for_you%rowtype;
  result_seen_at timestamptz;
  was_unseen boolean;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'authentication required';
  end if;

  select entry.* into target_item
  from public.left_for_you as entry
  where entry.id = target_item_id
    and entry.couple_id = private.current_couple_id()
    and entry.recipient_id = auth.uid()
  for update;

  if target_item.id is null then
    raise exception using errcode = '42501', message = 'left_item_recipient_required';
  end if;

  was_unseen := target_item.seen_at is null;

  if was_unseen then
    update public.left_for_you as entry
    set seen_at = now()
    where entry.id = target_item.id
      and entry.seen_at is null
    returning entry.seen_at into result_seen_at;

    if result_seen_at is null then
      select entry.seen_at into result_seen_at
      from public.left_for_you as entry
      where entry.id = target_item.id;
    end if;
  else
    result_seen_at := target_item.seen_at;
  end if;

  return jsonb_build_object(
    'id', target_item.id,
    'status', case when was_unseen then 'seen' else 'already_seen' end,
    'seen_at', result_seen_at
  );
end;
$function$;

-- public.register_push_token(push_token text, push_platform text)
CREATE OR REPLACE FUNCTION public.register_push_token(push_token text, push_platform text DEFAULT 'android'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  uid uuid := auth.uid();
  cid uuid;
begin
  if uid is null then
    raise exception 'Authentication required';
  end if;
  if push_token is null or length(trim(push_token)) < 16 then
    raise exception 'Invalid push token';
  end if;
  if push_platform not in ('android','ios') then
    raise exception 'Invalid push platform';
  end if;

  select couple_id into cid from public.profiles where id = uid;
  if cid is null then
    raise exception 'Profile not paired';
  end if;

  insert into public.device_push_tokens(user_id,couple_id,token,platform,last_seen_at)
  values(uid,cid,trim(push_token),push_platform,now())
  on conflict (token) do update
    set user_id = excluded.user_id,
        couple_id = excluded.couple_id,
        platform = excluded.platform,
        last_seen_at = now();
end;
$function$;
comment on function public.register_push_token(push_token text, push_platform text) is 'RETIRED (US 2.0 F1B): native push token RPC, never wired. EXECUTE revoked from public/anon/authenticated.';

-- public.register_web_push_subscription(target_endpoint text, target_p256dh text, target_auth text, target_expiration_time bigint, target_user_agent text)
CREATE OR REPLACE FUNCTION public.register_web_push_subscription(target_endpoint text, target_p256dh text, target_auth text, target_expiration_time bigint DEFAULT NULL::bigint, target_user_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid := auth.uid();
  cid uuid;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  if coalesce(length(trim(target_endpoint)),0) < 20 then raise exception 'Invalid push endpoint'; end if;
  if coalesce(length(trim(target_p256dh)),0) < 20 then raise exception 'Invalid p256dh key'; end if;
  if coalesce(length(trim(target_auth)),0) < 8 then raise exception 'Invalid auth key'; end if;

  select couple_id into cid from public.profiles where id = uid;
  if cid is null then raise exception 'Profile not linked'; end if;

  insert into public.push_subscriptions(user_id,couple_id,endpoint,p256dh,auth_key,expiration_time,user_agent,updated_at)
  values(uid,cid,target_endpoint,target_p256dh,target_auth,target_expiration_time,left(target_user_agent,500),now())
  on conflict(endpoint) do update set
    user_id = excluded.user_id,
    couple_id = excluded.couple_id,
    p256dh = excluded.p256dh,
    auth_key = excluded.auth_key,
    expiration_time = excluded.expiration_time,
    user_agent = excluded.user_agent,
    updated_at = now();

  return jsonb_build_object('active',true);
end;
$function$;

-- public.remove_web_push_subscription(target_endpoint text)
CREATE OR REPLACE FUNCTION public.remove_web_push_subscription(target_endpoint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid := auth.uid();
  removed_count integer := 0;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  delete from public.push_subscriptions where user_id = uid and endpoint = target_endpoint;
  get diagnostics removed_count = row_count;
  return jsonb_build_object('removed',removed_count > 0);
end;
$function$;

