  WHERE ((message.id = think_reactions.message_id) AND (message.kind = 'think'::text) AND (message.couple_id = private.current_couple_id()) AND ((message.sender_id = auth.uid()) OR (message.recipient_id = auth.uid()))))));
create policy weekly_quiz_rewards_same_couple_select on public.weekly_quiz_rewards as permissive for select to authenticated
  using ((EXISTS ( SELECT 1
   FROM profiles p
  WHERE ((p.id = auth.uid()) AND (p.couple_id = weekly_quiz_rewards.couple_id)))));

